const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location - Coastal Sage UCI station
  const station = ee.Geometry.Point([-117.70, 33.73]);

  // 2. Define time periods
  const jan2013Start = '2013-01-01';
  const jan2013End = '2013-02-01';
  const may2013Start = '2013-05-01';
  const may2013End = '2013-06-01';

  // 3. Load ERA5-Land soil moisture data
  const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/MONTHLY_AGGR');

  // 4. Get January 2013 data
  const jan2013 = era5
    .filterDate(jan2013Start, jan2013End)
    .select('volumetric_soil_water_layer_1');

  const jan2013Size = jan2013.size().getInfo();
  console.log('January 2013 images found:', jan2013Size);

  if (jan2013Size === 0) {
    console.log('No data for January 2013');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Get May 2013 data
  const may2013 = era5
    .filterDate(may2013Start, may2013End)
    .select('volumetric_soil_water_layer_1');

  const may2013Size = may2013.size().getInfo();
  console.log('May 2013 images found:', may2013Size);

  if (may2013Size === 0) {
    console.log('No data for May 2013');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Calculate mean soil moisture for each period
  const jan2013Mean = jan2013.mean();
  const may2013Mean = may2013.mean();

  // 7. Extract values at station location
  const janValue = jan2013Mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: station,
    scale: 11132,
    maxPixels: 1e9
  }).get('volumetric_soil_water_layer_1').getInfo();

  const mayValue = may2013Mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: station,
    scale: 11132,
    maxPixels: 1e9
  }).get('volumetric_soil_water_layer_1').getInfo();

  // 8. Validate results
  if (janValue === null || janValue === undefined) {
    console.log('Invalid January value');
    console.log('<answer>C3</answer>');
    return;
  }

  if (mayValue === null || mayValue === undefined) {
    console.log('Invalid May value');
    console.log('<answer>C3</answer>');
    return;
  }

  // 9. Print results
  console.log('January 2013 soil moisture (m3/m3):', janValue.toFixed(4));
  console.log('May 2013 soil moisture (m3/m3):', mayValue.toFixed(4));
  console.log('Difference (Jan - May):', (janValue - mayValue).toFixed(4));

  // 10. Final answer
  if (janValue > mayValue) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
